#!/bin/sh
# Customise the project generated by `tauri android init` (run from the repo root; GNU and BSD sed).
set -e
GEN=src-tauri/gen/android/app/src/main
# Servers are often plain http on the LAN or VPN.
grep -q usesCleartextTraffic "$GEN/AndroidManifest.xml" ||
  { sed -i.bak 's|<application|<application android:usesCleartextTraffic="true"|' "$GEN/AndroidManifest.xml" && rm "$GEN/AndroidManifest.xml.bak"; }
# Build-logic plugins also live on Maven Central; the plugin portal alone misses them on a fresh cache.
grep -q pluginManagement src-tauri/gen/android/settings.gradle ||
  { printf 'pluginManagement {\n    repositories {\n        gradlePluginPortal()\n        google()\n        mavenCentral()\n    }\n}\n\n'; cat src-tauri/gen/android/settings.gradle; } > src-tauri/gen/android/settings.tmp &&
  mv src-tauri/gen/android/settings.tmp src-tauri/gen/android/settings.gradle
grep -n "usesCleartextTraffic" "$GEN/AndroidManifest.xml"
